import java.io.*;import java.util.*;public class FlightPlanner {public static Map<String,List<String>> read(String f)throws IOException{Map<String,List<String>> m=new TreeMap<String,List<String>>();Scanner s=new Scanner(new File(f));while(s.hasNextLine()){String l=s.nextLine().trim();if(l.isEmpty())continue;String[] p=l.split("->");String a=p[0].trim(),b=p[1].trim();if(!m.containsKey(a))m.put(a,new ArrayList<String>());m.get(a).add(b);if(!m.containsKey(b))m.put(b,new ArrayList<String>());}s.close();return m;}public static void main(String[] a)throws Exception{Map<String,List<String>> flights=read(a.length>0?a[0]:"flights.txt");Scanner in=new Scanner(System.in);System.out.println("Available cities: "+flights.keySet());System.out.print("Start city: ");String start=in.nextLine().trim(),cur=start;ArrayList<String> route=new ArrayList<String>();route.add(cur);while(flights.containsKey(cur)&&!flights.get(cur).isEmpty()){List<String> d=flights.get(cur);System.out.println("Destinations from "+cur+": "+d);System.out.print("Next city: ");cur=in.nextLine().trim();route.add(cur);if(cur.equals(start))break;}System.out.println("Route: "+String.join(" -> ",route));in.close();}}
